//字模高度：41
//内部字体
//使用排序和二分查表
const lv_font_t myFont24 = {
    .dsc = &font_dsc,
    .get_glyph_bitmap = __user_font_get_bitmap,
    .get_glyph_dsc = __user_font_get_glyph_dsc,
    .line_height = 41,
    .base_line = 0,
};

